-- 2) Upsert Departamentos
INSERT INTO geografia.departamento (codigo, nombre, pais_id)
SELECT DISTINCT
  t.codigo_departamento,
  t.nombre_departamento,
  :pais_id
FROM tmp_geo_sifen t
WHERE t.codigo_departamento IS NOT NULL
ON CONFLICT (codigo, pais_id) DO UPDATE
  SET nombre = EXCLUDED.nombre,
      updated_at = CURRENT_TIMESTAMP;

-- 3) Upsert Distritos
INSERT INTO geografia.distrito (codigo, nombre, departamento_id)
SELECT DISTINCT
  t.codigo_distrito,
  t.nombre_distrito,
  d.id
FROM tmp_geo_sifen t
JOIN geografia.departamento d
  ON d.codigo = t.codigo_departamento AND d.pais_id = :pais_id
WHERE t.codigo_distrito IS NOT NULL
ON CONFLICT (codigo, departamento_id) DO UPDATE
  SET nombre = EXCLUDED.nombre,
      updated_at = CURRENT_TIMESTAMP;

-- 4) Upsert Ciudades
INSERT INTO geografia.ciudad (codigo, nombre, distrito_id)
SELECT DISTINCT
  t.codigo_ciudad,
  t.nombre_ciudad,
  di.id
FROM tmp_geo_sifen t
JOIN geografia.departamento d
  ON d.codigo = t.codigo_departamento AND d.pais_id = :pais_id
JOIN geografia.distrito di
  ON di.codigo = t.codigo_distrito AND di.departamento_id = d.id
WHERE t.codigo_ciudad IS NOT NULL
ON CONFLICT (codigo, distrito_id) DO UPDATE
  SET nombre = EXCLUDED.nombre,
      updated_at = CURRENT_TIMESTAMP;

-- 5) Upsert Barrios
INSERT INTO geografia.barrio (codigo, nombre, ciudad_id)
SELECT DISTINCT
  t.codigo_barrio,
  t.nombre_barrio,
  c.id
FROM tmp_geo_sifen t
JOIN geografia.departamento d
  ON d.codigo = t.codigo_departamento AND d.pais_id = :pais_id
JOIN geografia.distrito di
  ON di.codigo = t.codigo_distrito AND di.departamento_id = d.id
JOIN geografia.ciudad c
  ON c.codigo = t.codigo_ciudad AND c.distrito_id = di.id
WHERE t.codigo_barrio IS NOT NULL
  AND t.nombre_barrio IS NOT NULL
ON CONFLICT (codigo, ciudad_id) DO UPDATE
  SET nombre = EXCLUDED.nombre,
      updated_at = CURRENT_TIMESTAMP;

